# Generated by build.py from recipe.yml for recipe http-inject-a-fault. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site', 'flaky', 'accounts', 'accounts/uploads' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/hello.txt'), "hello from surl`n")
[IO.File]::WriteAllText((Join-Path $PWD 'flaky/hello.txt'), "hello from surl`n")
[IO.File]::WriteAllText((Join-Path $PWD 'flaky/slow.txt'), "slow`n")
[IO.File]::WriteAllText((Join-Path $PWD 'flaky/gone.txt'), "never sent`n")
[IO.File]::WriteAllText((Join-Path $PWD 'accounts/hello.txt'), "hello from surl`n")
[IO.File]::WriteAllText((Join-Path $PWD 'accounts/uploads/readme.txt'), "uploads land here`n")
[IO.File]::WriteAllText((Join-Path $PWD 'notes.txt'), "uploaded by curl`n")
$server0 = Start-Process surl -ArgumentList '--directory', 'site', '--fault', '"error;scheme=http;reply=503', 'Service', 'Unavailable;times=1"', 'http://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -s -o NUL -w "%{http_code}" http://127.0.0.1:8080/hello.txt } finally { Stop-Process $server0 }
